templates.prisma:
datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Users {
  id String @id @default(uuid()) // Unique identifier for the user.
  email String @unique // User's email address, used for login.
  password_hash String // Hashed password for secure authentication.
  name String? // User's display name.
  role String @default("'user'") // Role of the user in the platform (e.g., system administrator or regular user).
  created_at DateTime // Timestamp when the user account was created.
  updated_at DateTime // Timestamp when the user account was last updated.
}

model Workspaces {
  id String @id @default(uuid()) // Unique identifier for the workspace.
  name String // Name of the workspace.
  slug String @unique // URL-friendly unique identifier for the workspace.
  owner_id String // Foreign key referencing the user who owns this workspace.
  created_at DateTime // Timestamp when the workspace was created.
  updated_at DateTime // Timestamp when the workspace was last updated.

  // Relations:
  // [one-to-many] -> Users (via owner_id) [references]
}

model WorkspaceMembers {
  user_id String // Foreign key referencing the user.
  workspace_id String // Foreign key referencing the workspace.
  role String @default("'member'") // Role of the user within this specific workspace.
  joined_at DateTime // Timestamp when the user joined the workspace.
  updated_at DateTime // Timestamp when the membership was last updated (e.g., role change).
  id String @id @default(uuid())

  // Relations:
  // [many-to-many] -> Users (via user_id) [references]
  // [many-to-many] -> Workspaces (via workspace_id) [references]
}

model AIModels {
  id String @id @default(uuid()) // Unique identifier for the AI model.
  name String // Human-readable name of the model.
  provider String // Provider of the AI model (e.g., 'OpenAI', 'Anthropic').
  model_id_external String @unique // The external ID or slug used by the AI provider to identify the model.
  cost_per_million_input_tokens_usd Float? // Cost per million input tokens in USD.
  cost_per_million_output_tokens_usd Float? // Cost per million output tokens in USD.
  max_tokens Int? // Maximum number of tokens supported by the model.
  capabilities Json? // JSON object describing model capabilities (e.g., ['text_generation', 'image_generation']).
  is_active Boolean @default(true) // Indicates if the model is currently active and available.
  created_at DateTime // Timestamp when the model record was created.
  updated_at DateTime // Timestamp when the model record was last updated.
}

model AIRequests {
  id String @id @default(uuid()) // Unique identifier for the AI request.
  workspace_id String // Foreign key referencing the workspace where the request was made.
  user_id String // Foreign key referencing the user who made the request.
  model_id String // Foreign key referencing the AI model used.
  api_key_id String? // Foreign key referencing the API key used for programmatic requests.
  prompt_summary String? // A summary or truncated version of the input prompt for logging/display.
  input_tokens Int // Number of input tokens used in the request.
  output_tokens Int // Number of output tokens generated by the model.
  cost_usd Float // Calculated cost of the request in USD.
  latency_ms Int? // Latency of the AI model response in milliseconds.
  status String @default("'pending'") // Status of the AI request.
  error_message String? // Error message if the request failed.
  requested_at DateTime // Timestamp when the request was initiated.
  completed_at DateTime? // Timestamp when the request was completed (success or failure).

  // Relations:
  // [one-to-many] -> Workspaces (via workspace_id) [references]
  // [one-to-many] -> Users (via user_id) [references]
  // [one-to-many] -> AIModels (via model_id) [references]
  // [one-to-many] -> APIKeys (via api_key_id) [references]
}

model Subscriptions {
  id String @id @default(uuid()) // Unique identifier for the subscription record.
  workspace_id String @unique // Foreign key referencing the workspace that holds this subscription.
  stripe_customer_id String @unique // Stripe Customer ID associated with this workspace.
  stripe_subscription_id String? @unique // Stripe Subscription ID (if an active subscription exists).
  plan_id String // Foreign key referencing the internal plan definition.
  current_period_start DateTime? // Start of the current billing period.
  current_period_end DateTime? // End of the current billing period.
  status String @default("'trialing'") // Current status of the subscription.
  created_at DateTime // Timestamp when the subscription record was created.
  updated_at DateTime // Timestamp when the subscription record was last updated.

  // Relations:
  // [one-to-one] -> Workspaces (via workspace_id) [references]
}

model APIKeys {
  id String @id @default(uuid()) // Unique identifier for the API key record.
  workspace_id String // Foreign key referencing the workspace this API key belongs to.
  user_id String // Foreign key referencing the user who generated this API key.
  key_hash String @unique // Hashed value of the API key for secure storage.
  name String // User-defined name for the API key (e.g., 'My App Key').
  last_used_at DateTime? // Timestamp when the API key was last used.
  created_at DateTime // Timestamp when the API key was created.
  expires_at DateTime? // Optional expiration date for the API key.
  is_active Boolean @default(true) // Indicates if the API key is active and can be used.

  // Relations:
  // [one-to-many] -> Workspaces (via workspace_id) [references]
  // [one-to-many] -> Users (via user_id) [references]
}

