-- Database Type: PostgreSQL
-- Generated locally by ArchitectAI

CREATE TABLE IF NOT EXISTS "users" (
  "id" VARCHAR(255) PRIMARY KEY,
  "email" VARCHAR(255) NOT NULL UNIQUE,
  "password_hash" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255),
  "role" VARCHAR(255) NOT NULL DEFAULT ''user'',
  "created_at" TIMESTAMP NOT NULL DEFAULT 'now()',
  "updated_at" TIMESTAMP NOT NULL DEFAULT 'now()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_email" ON "users" ("email");
CREATE INDEX IF NOT EXISTS "idx_users_created_at" ON "users" ("created_at");

CREATE TABLE IF NOT EXISTS "workspaces" (
  "id" VARCHAR(255) PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL,
  "slug" VARCHAR(255) NOT NULL UNIQUE,
  "owner_id" VARCHAR(255) NOT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT 'now()',
  "updated_at" TIMESTAMP NOT NULL DEFAULT 'now()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_workspaces_slug" ON "workspaces" ("slug");
CREATE INDEX IF NOT EXISTS "idx_workspaces_owner_id" ON "workspaces" ("owner_id");

CREATE TABLE IF NOT EXISTS "workspacemembers" (
  "id" VARCHAR(255) PRIMARY KEY,
  "user_id" VARCHAR(255) NOT NULL,
  "workspace_id" VARCHAR(255) NOT NULL,
  "role" VARCHAR(255) NOT NULL DEFAULT ''member'',
  "joined_at" TIMESTAMP NOT NULL DEFAULT 'now()',
  "updated_at" TIMESTAMP NOT NULL DEFAULT 'now()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_workspacemembers_user_id_workspace_id" ON "workspacemembers" ("user_id", "workspace_id");
CREATE INDEX IF NOT EXISTS "idx_workspacemembers_workspace_id" ON "workspacemembers" ("workspace_id");

CREATE TABLE IF NOT EXISTS "aimodels" (
  "id" VARCHAR(255) PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL,
  "provider" VARCHAR(255) NOT NULL,
  "model_id_external" VARCHAR(255) NOT NULL UNIQUE,
  "cost_per_million_input_tokens_usd" NUMERIC,
  "cost_per_million_output_tokens_usd" NUMERIC,
  "max_tokens" INTEGER,
  "capabilities" JSONB DEFAULT '{}',
  "is_active" BOOLEAN NOT NULL DEFAULT true,
  "created_at" TIMESTAMP NOT NULL DEFAULT 'now()',
  "updated_at" TIMESTAMP NOT NULL DEFAULT 'now()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_aimodels_model_id_external" ON "aimodels" ("model_id_external");
CREATE INDEX IF NOT EXISTS "idx_aimodels_provider_is_active" ON "aimodels" ("provider", "is_active");

CREATE TABLE IF NOT EXISTS "airequests" (
  "id" VARCHAR(255) PRIMARY KEY,
  "workspace_id" VARCHAR(255) NOT NULL,
  "user_id" VARCHAR(255) NOT NULL,
  "model_id" VARCHAR(255) NOT NULL,
  "api_key_id" VARCHAR(255),
  "prompt_summary" VARCHAR(255),
  "input_tokens" INTEGER NOT NULL,
  "output_tokens" INTEGER NOT NULL,
  "cost_usd" NUMERIC NOT NULL,
  "latency_ms" INTEGER,
  "status" VARCHAR(255) NOT NULL DEFAULT ''pending'',
  "error_message" VARCHAR(255),
  "requested_at" TIMESTAMP NOT NULL DEFAULT 'now()',
  "completed_at" TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "idx_airequests_workspace_id_requested_at" ON "airequests" ("workspace_id", "requested_at");
CREATE INDEX IF NOT EXISTS "idx_airequests_user_id_requested_at" ON "airequests" ("user_id", "requested_at");
CREATE INDEX IF NOT EXISTS "idx_airequests_model_id" ON "airequests" ("model_id");
CREATE INDEX IF NOT EXISTS "idx_airequests_api_key_id" ON "airequests" ("api_key_id");

CREATE TABLE IF NOT EXISTS "subscriptions" (
  "id" VARCHAR(255) PRIMARY KEY,
  "workspace_id" VARCHAR(255) NOT NULL UNIQUE,
  "stripe_customer_id" VARCHAR(255) NOT NULL UNIQUE,
  "stripe_subscription_id" VARCHAR(255) UNIQUE,
  "plan_id" VARCHAR(255) NOT NULL,
  "current_period_start" TIMESTAMP,
  "current_period_end" TIMESTAMP,
  "status" VARCHAR(255) NOT NULL DEFAULT ''trialing'',
  "created_at" TIMESTAMP NOT NULL DEFAULT 'now()',
  "updated_at" TIMESTAMP NOT NULL DEFAULT 'now()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_subscriptions_workspace_id" ON "subscriptions" ("workspace_id");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_subscriptions_stripe_customer_id" ON "subscriptions" ("stripe_customer_id");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_subscriptions_stripe_subscription_id" ON "subscriptions" ("stripe_subscription_id");
CREATE INDEX IF NOT EXISTS "idx_subscriptions_status" ON "subscriptions" ("status");

CREATE TABLE IF NOT EXISTS "apikeys" (
  "id" VARCHAR(255) PRIMARY KEY,
  "workspace_id" VARCHAR(255) NOT NULL,
  "user_id" VARCHAR(255) NOT NULL,
  "key_hash" VARCHAR(255) NOT NULL UNIQUE,
  "name" VARCHAR(255) NOT NULL,
  "last_used_at" TIMESTAMP,
  "created_at" TIMESTAMP NOT NULL DEFAULT 'now()',
  "expires_at" TIMESTAMP,
  "is_active" BOOLEAN NOT NULL DEFAULT true
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_apikeys_key_hash" ON "apikeys" ("key_hash");
CREATE INDEX IF NOT EXISTS "idx_apikeys_workspace_id_is_active" ON "apikeys" ("workspace_id", "is_active");
CREATE INDEX IF NOT EXISTS "idx_apikeys_user_id" ON "apikeys" ("user_id");

