/**
 * Mongoose Models
 * Generated locally by ArchitectAI
 */

const mongoose = require('mongoose');

// --- Users Schema ---
const UsersSchema = new mongoose.Schema({
  email: {
    type: String,
    required: true,
    unique: true,
    description: "User's email address, used for login."
  },
  password_hash: {
    type: String,
    required: true,
    description: "Hashed password for secure authentication."
  },
  name: {
    type: String,
    required: false,
    description: "User's display name."
  },
  role: {
    type: String,
    required: true,
    default: "'user'",
    description: "Role of the user in the platform (e.g., system administrator or regular user)."
  },
  created_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the user account was created."
  },
  updated_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the user account was last updated."
  },
}, {
  timestamps: true
});

UsersSchema.index({"email":1}, {"unique":true});
UsersSchema.index({"created_at":1}, {"unique":false});
const Users = mongoose.model('Users', UsersSchema);

// --- Workspaces Schema ---
const WorkspacesSchema = new mongoose.Schema({
  name: {
    type: String,
    required: true,
    description: "Name of the workspace."
  },
  slug: {
    type: String,
    required: true,
    unique: true,
    description: "URL-friendly unique identifier for the workspace."
  },
  owner_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the user who owns this workspace."
  },
  created_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the workspace was created."
  },
  updated_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the workspace was last updated."
  },
}, {
  timestamps: true
});

WorkspacesSchema.index({"slug":1}, {"unique":true});
WorkspacesSchema.index({"owner_id":1}, {"unique":false});
const Workspaces = mongoose.model('Workspaces', WorkspacesSchema);

// --- WorkspaceMembers Schema ---
const WorkspaceMembersSchema = new mongoose.Schema({
  user_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the user."
  },
  workspace_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the workspace."
  },
  role: {
    type: String,
    required: true,
    default: "'member'",
    description: "Role of the user within this specific workspace."
  },
  joined_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the user joined the workspace."
  },
  updated_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the membership was last updated (e.g., role change)."
  },
}, {
  timestamps: true
});

WorkspaceMembersSchema.index({"user_id":1,"workspace_id":1}, {"unique":true});
WorkspaceMembersSchema.index({"workspace_id":1}, {"unique":false});
const WorkspaceMembers = mongoose.model('WorkspaceMembers', WorkspaceMembersSchema);

// --- AIModels Schema ---
const AIModelsSchema = new mongoose.Schema({
  name: {
    type: String,
    required: true,
    description: "Human-readable name of the model."
  },
  provider: {
    type: String,
    required: true,
    description: "Provider of the AI model (e.g., 'OpenAI', 'Anthropic')."
  },
  model_id_external: {
    type: String,
    required: true,
    unique: true,
    description: "The external ID or slug used by the AI provider to identify the model."
  },
  cost_per_million_input_tokens_usd: {
    type: Number,
    required: false,
    description: "Cost per million input tokens in USD."
  },
  cost_per_million_output_tokens_usd: {
    type: Number,
    required: false,
    description: "Cost per million output tokens in USD."
  },
  max_tokens: {
    type: Number,
    required: false,
    description: "Maximum number of tokens supported by the model."
  },
  capabilities: {
    type: mongoose.Schema.Types.Mixed,
    required: false,
    default: {},
    description: "JSON object describing model capabilities (e.g., ['text_generation', 'image_generation'])."
  },
  is_active: {
    type: Boolean,
    required: true,
    default: true,
    description: "Indicates if the model is currently active and available."
  },
  created_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the model record was created."
  },
  updated_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the model record was last updated."
  },
}, {
  timestamps: true
});

AIModelsSchema.index({"model_id_external":1}, {"unique":true});
AIModelsSchema.index({"provider":1,"is_active":1}, {"unique":false});
const AIModels = mongoose.model('AIModels', AIModelsSchema);

// --- AIRequests Schema ---
const AIRequestsSchema = new mongoose.Schema({
  workspace_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the workspace where the request was made."
  },
  user_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the user who made the request."
  },
  model_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the AI model used."
  },
  api_key_id: {
    type: String,
    required: false,
    description: "Foreign key referencing the API key used for programmatic requests."
  },
  prompt_summary: {
    type: String,
    required: false,
    description: "A summary or truncated version of the input prompt for logging/display."
  },
  input_tokens: {
    type: Number,
    required: true,
    description: "Number of input tokens used in the request."
  },
  output_tokens: {
    type: Number,
    required: true,
    description: "Number of output tokens generated by the model."
  },
  cost_usd: {
    type: Number,
    required: true,
    description: "Calculated cost of the request in USD."
  },
  latency_ms: {
    type: Number,
    required: false,
    description: "Latency of the AI model response in milliseconds."
  },
  status: {
    type: String,
    required: true,
    default: "'pending'",
    description: "Status of the AI request."
  },
  error_message: {
    type: String,
    required: false,
    description: "Error message if the request failed."
  },
  requested_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the request was initiated."
  },
  completed_at: {
    type: Date,
    required: false,
    description: "Timestamp when the request was completed (success or failure)."
  },
}, {
  timestamps: true
});

AIRequestsSchema.index({"workspace_id":1,"requested_at":1}, {"unique":false});
AIRequestsSchema.index({"user_id":1,"requested_at":1}, {"unique":false});
AIRequestsSchema.index({"model_id":1}, {"unique":false});
AIRequestsSchema.index({"api_key_id":1}, {"unique":false});
const AIRequests = mongoose.model('AIRequests', AIRequestsSchema);

// --- Subscriptions Schema ---
const SubscriptionsSchema = new mongoose.Schema({
  workspace_id: {
    type: String,
    required: true,
    unique: true,
    description: "Foreign key referencing the workspace that holds this subscription."
  },
  stripe_customer_id: {
    type: String,
    required: true,
    unique: true,
    description: "Stripe Customer ID associated with this workspace."
  },
  stripe_subscription_id: {
    type: String,
    required: false,
    unique: true,
    description: "Stripe Subscription ID (if an active subscription exists)."
  },
  plan_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the internal plan definition."
  },
  current_period_start: {
    type: Date,
    required: false,
    description: "Start of the current billing period."
  },
  current_period_end: {
    type: Date,
    required: false,
    description: "End of the current billing period."
  },
  status: {
    type: String,
    required: true,
    default: "'trialing'",
    description: "Current status of the subscription."
  },
  created_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the subscription record was created."
  },
  updated_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the subscription record was last updated."
  },
}, {
  timestamps: true
});

SubscriptionsSchema.index({"workspace_id":1}, {"unique":true});
SubscriptionsSchema.index({"stripe_customer_id":1}, {"unique":true});
SubscriptionsSchema.index({"stripe_subscription_id":1}, {"unique":true});
SubscriptionsSchema.index({"status":1}, {"unique":false});
const Subscriptions = mongoose.model('Subscriptions', SubscriptionsSchema);

// --- APIKeys Schema ---
const APIKeysSchema = new mongoose.Schema({
  workspace_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the workspace this API key belongs to."
  },
  user_id: {
    type: String,
    required: true,
    description: "Foreign key referencing the user who generated this API key."
  },
  key_hash: {
    type: String,
    required: true,
    unique: true,
    description: "Hashed value of the API key for secure storage."
  },
  name: {
    type: String,
    required: true,
    description: "User-defined name for the API key (e.g., 'My App Key')."
  },
  last_used_at: {
    type: Date,
    required: false,
    description: "Timestamp when the API key was last used."
  },
  created_at: {
    type: Date,
    required: true,
    default: now(),
    description: "Timestamp when the API key was created."
  },
  expires_at: {
    type: Date,
    required: false,
    description: "Optional expiration date for the API key."
  },
  is_active: {
    type: Boolean,
    required: true,
    default: true,
    description: "Indicates if the API key is active and can be used."
  },
}, {
  timestamps: true
});

APIKeysSchema.index({"key_hash":1}, {"unique":true});
APIKeysSchema.index({"workspace_id":1,"is_active":1}, {"unique":false});
APIKeysSchema.index({"user_id":1}, {"unique":false});
const APIKeys = mongoose.model('APIKeys', APIKeysSchema);

module.exports = {
  Users,
